def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_moves = [o for _, o in history]
    last_my, last_opp = history[-1]
    opp_def_total = sum(1 for o in opp_moves if o == 'D')
    if opp_def_total >= 3 and opp_def_total * 2 > n:
        return 'D'
    if n >= 5:
        first5_all_c = True
        for i in range(5):
            if opp_moves[i] == 'D':
                first5_all_c = False
                break
        if first5_all_c:
            first_def = None
            for i in range(5, n):
                if opp_moves[i] == 'D':
                    first_def = i
                    break
            if first_def is None:
                return 'D'
            else:
                defs_since = sum(1 for i in range(first_def, n) if opp_moves[i] == 'D')
                if defs_since <= 2:
                    return 'C'
                else:
                    return 'D'
    if last_opp == 'D':
        if opp_def_total < n and rng.random() < 0.1:
            return 'C'
        return 'D'
    return 'C'
